use once_cell::sync::Lazy;
use std::sync::Mutex;

/// Estructura interna para estadísticas y parámetros Beta.
#[derive(Clone, Debug)]
struct InnerStats {
    // Beta prior parameters: a for "success" (tile==4), b for "failure" (tile==2)
    a: u32,
    b: u32,
    total_fours: u32,
    total_twos: u32,
    p_move_probs: Vec<f32>, // historial de probabilidades esperadas por turno
    enabled: bool,
}

impl Default for InnerStats {
    fn default() -> Self {
        // Prior: expectation 0.1 => a/(a+b) = 0.1 -> choose a=1, b=9
        InnerStats { a: 1, b: 9, total_fours: 0, total_twos: 0, p_move_probs: Vec::new(), enabled: false }
    }
}

static STATS: Lazy<Mutex<InnerStats>> = Lazy::new(|| Mutex::new(InnerStats::default()));

/// Vista publica de las estadísticas para uso en UI.
#[derive(Clone, Debug)]
pub struct StatsView {
    pub posterior_mean: f32,
    pub total_fours: u32,
    pub total_twos: u32,
    pub p_move_probs: Vec<f32>,
}

pub fn enable() {
    let mut s = STATS.lock().unwrap();
    s.enabled = true;
}

pub fn disable() {
    let mut s = STATS.lock().unwrap();
    s.enabled = false;
}

pub fn reset_stats_for_new_game() {
    let mut s = STATS.lock().unwrap();
    *s = InnerStats::default();
    s.enabled = true; // keep enabled after reset when called from UI
}

pub fn record_observed_two() {
    let mut s = STATS.lock().unwrap();
    if !s.enabled { return; }
    s.b += 1;
    s.total_twos += 1;
}

pub fn record_observed_four() {
    let mut s = STATS.lock().unwrap();
    if !s.enabled { return; }
    s.a += 1;
    s.total_fours += 1;
}

/// Registra la probabilidad esperada (según el árbol de búsqueda) de que el siguiente tile sea 4 en este movimiento.
pub fn record_p_move_prob(p: f32) {
    let mut s = STATS.lock().unwrap();
    if !s.enabled { return; }
    // mantener sólo las últimas 200 entradas para evitar crecer indefinidamente
    s.p_move_probs.push(p.clamp(0.0, 1.0));
    if s.p_move_probs.len() > 200 {
        let excess = s.p_move_probs.len() - 200;
        s.p_move_probs.drain(0..excess);
    }
}

pub fn get_stats() -> StatsView {
    let s = STATS.lock().unwrap();
    let posterior_mean = (s.a as f32) / ((s.a + s.b) as f32);
    StatsView { posterior_mean, total_fours: s.total_fours, total_twos: s.total_twos, p_move_probs: s.p_move_probs.clone() }
}

pub fn print_summary() {
    let s = STATS.lock().unwrap();
    if !s.enabled { return; }
    println!("Bayes posterior mean p(4) = {:.4}", (s.a as f32) / ((s.a + s.b) as f32));
    println!("Total observed 4s: {}", s.total_fours);
    println!("Total observed 2s: {}", s.total_twos);
    if !s.p_move_probs.is_empty() {
        let avg: f32 = s.p_move_probs.iter().sum::<f32>() / (s.p_move_probs.len() as f32);
        println!("Average recorded p_move (last {}): {:.4}", s.p_move_probs.len(), avg);
    }
}

#![allow(unused)]

use std::time::{Duration, Instant};

use anyhow::Context;
use board::PlayableBoard;
use clap::Parser;
use rayon::prelude::*;

mod board;
mod eval;
mod search;

#[derive(Parser, Debug)]
#[command(version, about, long_about = None)]
struct Args {
    /// Time in seconds allowed for a single game
    #[arg(short, long, default_value = "600")]
    timeout: u64,

    /// Number of games to play
    #[arg(short, long, default_value = "8")]
    num_games: u64,
}

fn main() -> anyhow::Result<()> {
    // retrieve command line arguments
    let args: Args = Args::parse();

    // number of game to play
    let num_games = args.num_games;
    // maximum allow runtime for each game
    let timeout = Duration::from_secs(args.timeout);

    // configure the global thread pool of rayon to have as many threads as we have *physical* CPUs
    rayon::ThreadPoolBuilder::new()
        .num_threads(num_cpus::get_physical())
        .build_global()
        .unwrap();

    // run all games on the thread pool and collect the results
    let results: Vec<_> = (0..num_games)
        .into_par_iter()
        .map(|_i| play(timeout))
        .collect();

    // print all results
    for res in &results {
        match res {
            // This line now works correctly due to Display implementation in board.rs
            Ok((score, board)) => println!("score (#actions): {score}\n{board}\n"),
            Err(e) => println!("{e}"),
        }
    }

    // print statistic over the valid runs
    let valid_results: Vec<_> = results.iter().filter_map(|x| x.as_ref().ok()).collect();
    println!("How many time a tile was reached:");
    for tile in 3..=15 {
        let mut count = 0;
        for (_, board) in &valid_results {
            if board.has_at_least_tile(tile) {
                count += 1;
            }
        }
        println!(
            "{:>6}: {:>6.2}%",
            2u32.pow(tile as u32),
            (count as f32) / (num_games as f32) * 100.0
        );
    }
    println!("\nNumber of successful games: {}", valid_results.len());
    println!(
        "Number of game with error:  {}",
        results.len() - valid_results.len()
    );
    let average_score: f32 =
        valid_results.iter().map(|(score, _)| *score).sum::<f32>() / (valid_results.len() as f32);
    println!("Average score (#actions):   {:6.2}", average_score);

    Ok(())
}

/// Play a game with the given `timeout
fn play(timeout: Duration) -> anyhow::Result<(f32, PlayableBoard)> {
    // timestamp of when we started to play
    let start = Instant::now();

    // count of the number of move played
    let mut num_moves = 0;
    let mut board = PlayableBoard::init();

    loop {
        let Some(action) = crate::search::select_action(board) else {
            println!("End game // num moves {num_moves}");
            return Ok((num_moves as f32, board));
        };

        if start.elapsed() > timeout {
            println!("Timeout // num moves: {num_moves}");
            return Ok((num_moves as f32, board));
        }

        //println!("GOT ========================> {action:?}");
        num_moves += 1;
        let played = board
            .apply(action)
            // This 'format!' call now works because PlayableBoard implements Display
            .with_context(|| format!("Got inapplicable action {action:?} on board\n{board}"))?;
        board = played.with_random_tile();
    }
}

